import os, pathlib, tempfile
HERE = os.path.dirname(os.path.abspath(__file__)); os.chdir(HERE)
APP = pathlib.Path(HERE).parent.joinpath('inkling.html').as_uri()
import asyncio
from playwright.async_api import async_playwright
async def sub(pg, top, item):
    await pg.hover('.menu:not(.sub) button:has-text("%s")' % top); await pg.wait_for_timeout(350)
    await pg.click('.menu.sub button:has-text("%s")' % item)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); pg = await b.new_page(viewport={'width':1440,'height':900})
        errs=[]; pg.on('pageerror', lambda e: errs.append(str(e)))
        await pg.add_init_script(open('mock3d.js').read())
        await pg.goto(APP); await pg.wait_for_timeout(900)
        await pg.click('#newNotebook'); await pg.fill('.modal input.field', 'K'); await pg.keyboard.press('Enter'); await pg.wait_for_timeout(300)
        await (await pg.query_selector_all('.kind'))[2].click(); await pg.click('.modal .btn.primary'); await pg.wait_for_timeout(600)
        await pg.click('#rail button[aria-pressed="true"]'); await pg.wait_for_timeout(200)
        await pg.click('.rtabs button:has-text("Insert")')
        await pg.click('#ribbon button[aria-label="Movable A4 page"]'); await pg.click('.menu button:has-text("A4 portrait")'); await pg.wait_for_timeout(400)
        pb = await (await pg.query_selector('.obj-paper')).bounding_box()
        await pg.mouse.click(pb['x']+pb['width']/2, pb['y']+60); await pg.wait_for_timeout(250); await pg.mouse.click(pb['x']+pb['width']/2, pb['y']+60); await pg.wait_for_timeout(250)
        await pg.keyboard.type('Blatt eins'); await pg.keyboard.press('Escape'); await pg.wait_for_timeout(300)
        await pg.click('#dock [data-tool="pen"]'); await pg.mouse.move(pb['x']+50, pb['y']+250); await pg.mouse.down(); await pg.mouse.move(pb['x']+150, pb['y']+270, steps=6); await pg.mouse.up()
        await pg.click('#dock [data-tool="select"]')
        await pg.click('#dock button[aria-label="Note box (N)"]'); await pg.keyboard.type('Auf dem Blatt'); await pg.keyboard.press('Escape'); await pg.wait_for_timeout(150)
        nt = (await pg.query_selector_all('.obj-note'))[0]; nb = await nt.bounding_box()
        await pg.mouse.move(nb['x']+20, nb['y']+10); await pg.mouse.down(); await pg.mouse.move(pb['x']+90, pb['y']+pb['height']*0.6, steps=8); await pg.mouse.up(); await pg.mouse.click(1300, 760)
        count = lambda: pg.evaluate("[document.querySelectorAll('.obj-paper').length, document.querySelectorAll('.obj-note').length, document.querySelectorAll('svg path[data-id]').length]")
        print('start [sheets, notes, drawings]:', await count())
        await pg.click('#dock .dock-caret'); await pg.wait_for_timeout(300)
        print('paste chooser:', await pg.evaluate("[...document.querySelectorAll('.menu:not(.sub) > button,.menu:not(.sub) > .mlabel')].map(b=>b.innerText.trim())"))
        await sub(pg, 'A4 page', 'Copy with everything on it'); await pg.wait_for_timeout(500)
        print('after copy:', await count(), '| texts:', await pg.evaluate("[...document.querySelectorAll('.obj-paper .otext')].map(t=>t.innerText)"))
        await pg.mouse.click(1300, 760); await pg.click('#dock .paste-go'); await pg.wait_for_timeout(500)
        xs = await pg.evaluate("[...document.querySelectorAll('.obj-paper')].map(e=>Math.round(e.getBoundingClientRect().x))")
        print('Paste button again:', await count(), '| sheets side by side (x):', xs, '| button:', await pg.get_attribute('#dock .paste-go', 'title'))
        await pg.click('#dock .dock-caret'); await pg.wait_for_timeout(300); await sub(pg, 'A4 page 3', 'Empty sheet like this one'); await pg.wait_for_timeout(400)
        print('empty look-alike:', await count(), '| last text empty:', await pg.evaluate("[...document.querySelectorAll('.obj-paper .otext')].pop().innerText.trim() === ''"))
        await pg.click('#dock .dock-caret'); await pg.wait_for_timeout(300); await sub(pg, 'New blank sheet', 'A3 landscape'); await pg.wait_for_timeout(400)
        print('new A3 landscape:', await pg.evaluate("[...document.querySelectorAll('.obj-paper .paper-tag')].map(t=>t.innerText)"))
        # Ctrl+D on the first sheet
        await pg.keyboard.press('Control+k'); await pg.keyboard.type('Blatt eins'); await pg.wait_for_timeout(250); await pg.keyboard.press('Enter'); await pg.wait_for_timeout(400)
        c0 = await count(); await pg.keyboard.press('Control+d'); await pg.wait_for_timeout(400)
        print('Ctrl+D on a sheet:', c0, '->', await count(), '| copy placed beside the original:', await pg.evaluate("(()=>{const s=[...document.querySelectorAll('.obj-paper')].filter(e=>e.querySelector('.otext').innerText.includes('Blatt eins')).map(e=>e.getBoundingClientRect()); return s.length>=2 && s.every((a,i)=>s.every((b,j)=>i===j || a.right<=b.left+1 || b.right<=a.left+1 || a.bottom<=b.top+1 || b.bottom<=a.top+1))})()"))
        # save as a block and paste it back
        await pg.keyboard.press('Control+k'); await pg.keyboard.type('Blatt eins'); await pg.wait_for_timeout(250); await pg.keyboard.press('Enter'); await pg.wait_for_timeout(400)
        sel = await pg.evaluate("(()=>{const b=document.querySelector('.selbox'); const r=b.getBoundingClientRect(); return [r.x+r.width-25, r.y+r.height/2]})()")
        await pg.mouse.click(sel[0], sel[1], button='right'); await pg.wait_for_timeout(200)
        await pg.click('.menu button:has-text("Save as a block")'); await pg.wait_for_timeout(200)
        print('suggested name:', await pg.input_value('.modal input')); await pg.click('.modal .btn.primary'); await pg.wait_for_timeout(500)
        await pg.click('#blocksBtn'); await pg.wait_for_timeout(400)
        print('blocks folder:', (await pg.inner_text('.modal .modal-body')).replace('\n', ' | ')[160:330])
        c1 = await count(); await pg.click('.modal .mrow button:has-text("Paste")'); await pg.wait_for_timeout(500)
        print('pasted the sheet block:', c1, '->', await count())
        print('ERRORS', errs[:5])
        await b.close()
asyncio.run(main())
